10.2 Código C++
#include &lt;iostream&gt;
using namespace std;

int main() {
    int num1, num2, resultado;
    char operador;

    cout &lt;&lt; "Ingrese el primer numero: ";
    cin &gt;&gt; num1;

    cout &lt;&lt; "Ingrese el segundo numero: ";
    cin &gt;&gt; num2;

    cout &lt;&lt; "Ingrese la operacion (+, -, *, /, %): ";
    cin &gt;&gt; operador;

    switch (operador) {
        case '+':
            resultado = num1 + num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            break;

        case '-':
            resultado = num1 - num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            break;

        case '*':
            resultado = num1 * num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            break;

        case '/':
            if (num2 == 0) {
                cout &lt;&lt; "Error: no se puede dividir entre cero." 
                     &lt;&lt; endl;
            } else {
                resultado = num1 / num2;
                cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            }
            break;

        case '%':
            if (num2 == 0) {
                cout &lt;&lt; "Error: no se puede obtener residuo entre cero." 
                     &lt;&lt; endl;
            } else {
                resultado = num1 % num2;
                cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            }
            break;

        default:
            cout &lt;&lt; "Operacion no valida." &lt;&lt; endl;
    }

    return 0;
}

12.3 Código C++
#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

int main() {
    string nombre;
    string clasificacion;
    int edad;

    cout &lt;&lt; "Ingrese su nombre: ";
    getline(cin, nombre);

    cout &lt;&lt; "Ingrese su edad: ";
    cin &gt;&gt; edad;

    if (edad &lt;= 0) {
        cout &lt;&lt; "Edad invalida." &lt;&lt; endl;

    } else if (edad &lt; 18) {
        clasificacion = "Menor de edad";

    } else if (edad &lt;= 45) {
        clasificacion = "Joven adulto";

    } else if (edad &lt;= 60) {
        clasificacion = "Adulto";

    } else {
        clasificacion = "Adulto mayor";
    }

    if (edad &gt; 0) {
        cout &lt;&lt; "\nNombre: " &lt;&lt; nombre &lt;&lt; endl;
        cout &lt;&lt; "Edad: " &lt;&lt; edad &lt;&lt; endl;
        cout &lt;&lt; "Clasificacion: " &lt;&lt; clasificacion &lt;&lt; endl;
    }

    return 0;
}

